import{_ as a,a as t,c as n,ac as l}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第一册：英语初阶 · 全册易错点 · 第132–144课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第一册：英语初阶 · 全册易错点 · 第132–144课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-1/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第106–131课","link":"/life/english/new-concept/book-1/mistakes-part-05"},"next":{"text":"第一册：英语初阶 · 综合复习与自测","link":"/life/english/new-concept/book-1/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第106–131课","link":"/life/english/new-concept/book-1/mistakes-part-05"},"next":{"text":"第一册：英语初阶 · 综合复习与自测","link":"/life/english/new-concept/book-1/review"}},"headers":[],"relativePath":"life/english/new-concept/book-1/mistakes-part-06.md","filePath":"life/english/new-concept/book-1/mistakes-part-06.md"}'),i={name:"life/english/new-concept/book-1/mistakes-part-06.md"};function o(s,e,r,h,p,d){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="第一册-英语初阶-·-全册易错点-·-第132–144课" tabindex="-1">第一册：英语初阶 · 全册易错点 · 第132–144课 <a class="header-anchor" href="#第一册-英语初阶-·-全册易错点-·-第132–144课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册易错点 · 第132–144课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="l132-·-may-might-的时间层次" tabindex="-1">L132 · may/might 的时间层次 <a class="header-anchor" href="#l132-·-may-might-的时间层次" aria-label="Permalink to &quot;L132 · may/might 的时间层次 {#l132-·-may-might-的时间层次}&quot;">​</a></h2><p>may not arrive 表可能不到，不是“不可能到”；不要夸大确定程度。</p><p><strong>对照例句：</strong> Ella might have left her phone on the train.</p><p>Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-132">回看讲解和练习</a></p><h2 id="l133-·-间接引语的时态回移" tabindex="-1">L133 · 间接引语的时态回移 <a class="header-anchor" href="#l133-·-间接引语的时态回移" aria-label="Permalink to &quot;L133 · 间接引语的时态回移 {#l133-·-间接引语的时态回移}&quot;">​</a></h2><p>told that 通常缺少听话者；用 told us that 或 said that。</p><p><strong>对照例句：</strong> The reporter said that the bridge was closed.</p><p>Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-133">回看讲解和练习</a></p><h2 id="l134-·-间接引语的时态回移" tabindex="-1">L134 · 间接引语的时态回移 <a class="header-anchor" href="#l134-·-间接引语的时态回移" aria-label="Permalink to &quot;L134 · 间接引语的时态回移 {#l134-·-间接引语的时态回移}&quot;">​</a></h2><p>told that 通常缺少听话者；用 told us that 或 said that。</p><p><strong>对照例句：</strong> Maya told us that she was studying abroad.</p><p>Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-134">回看讲解和练习</a></p><h2 id="l135-·-would-与-had-done-的回移" tabindex="-1">L135 · would 与 had done 的回移 <a class="header-anchor" href="#l135-·-would-与-had-done-的回移" aria-label="Permalink to &quot;L135 · would 与 had done 的回移 {#l135-·-would-与-had-done-的回移}&quot;">​</a></h2><p>would 后用 send 原形；had 后用 finished 分词，两种形式不要互换。</p><p><strong>对照例句：</strong> He said he would send the document the next day.</p><p>Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-135">回看讲解和练习</a></p><h2 id="l136-·-would-与-had-done-的回移" tabindex="-1">L136 · would 与 had done 的回移 <a class="header-anchor" href="#l136-·-would-与-had-done-的回移" aria-label="Permalink to &quot;L136 · would 与 had done 的回移 {#l136-·-would-与-had-done-的回移}&quot;">​</a></h2><p>would 后用 send 原形；had 后用 finished 分词，两种形式不要互换。</p><p><strong>对照例句：</strong> She told me she had finished the repairs.</p><p>Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-136">回看讲解和练习</a></p><h2 id="l137-·-真实条件句" tabindex="-1">L137 · 真实条件句 <a class="header-anchor" href="#l137-·-真实条件句" aria-label="Permalink to &quot;L137 · 真实条件句 {#l137-·-真实条件句}&quot;">​</a></h2><p>本课普通未来条件用 if it rains，而非 if it will rain。</p><p><strong>对照例句：</strong> If we finish early, we will take a walk.</p><p>If we finish early 为条件，用一般现在时；we will take a walk 为条件成立后的结果，用 will 加原形。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-137">回看讲解和练习</a></p><h2 id="l138-·-真实条件句" tabindex="-1">L138 · 真实条件句 <a class="header-anchor" href="#l138-·-真实条件句" aria-label="Permalink to &quot;L138 · 真实条件句 {#l138-·-真实条件句}&quot;">​</a></h2><p>本课普通未来条件用 if it rains，而非 if it will rain。</p><p><strong>对照例句：</strong> We will stay indoors if it rains tomorrow.</p><p>主句 will stay 表结果，后置 if it rains tomorrow 表未来条件；rains 用现在时，不机械改 will rain。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-138">回看讲解和练习</a></p><h2 id="l139-·-间接疑问句的陈述语序" tabindex="-1">L139 · 间接疑问句的陈述语序 <a class="header-anchor" href="#l139-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;L139 · 间接疑问句的陈述语序 {#l139-·-间接疑问句的陈述语序}&quot;">​</a></h2><p>从句写 when the meeting starts，不写 when does the meeting start。</p><p><strong>对照例句：</strong> She wants to know whether the office is open.</p><p>Wants to know 是主句谓语结构；whether 表“是否”，从句 the office is open 采用陈述语序。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-139">回看讲解和练习</a></p><h2 id="l140-·-间接疑问句的陈述语序" tabindex="-1">L140 · 间接疑问句的陈述语序 <a class="header-anchor" href="#l140-·-间接疑问句的陈述语序" aria-label="Permalink to &quot;L140 · 间接疑问句的陈述语序 {#l140-·-间接疑问句的陈述语序}&quot;">​</a></h2><p>从句写 when the meeting starts，不写 when does the meeting start。</p><p><strong>对照例句：</strong> Could you tell me when the meeting starts?</p><p>Could you tell me 是外层礼貌问句；内层 when the meeting starts 是间接疑问，不能再加 does 倒装。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-140">回看讲解和练习</a></p><h2 id="l141-·-一般过去时被动语态" tabindex="-1">L141 · 一般过去时被动语态 <a class="header-anchor" href="#l141-·-一般过去时被动语态" aria-label="Permalink to &quot;L141 · 一般过去时被动语态 {#l141-·-一般过去时被动语态}&quot;">​</a></h2><p>by email 表方式，不是执行者；被动中的 built 是分词，不是 build 原形。</p><p><strong>对照例句：</strong> The guests were invited by email.</p><p>The guests 为被邀请者，were invited 为过去被动；by email 表通过邮件这一方式，并非动作执行者。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-141">回看讲解和练习</a></p><h2 id="l142-·-一般过去时被动语态" tabindex="-1">L142 · 一般过去时被动语态 <a class="header-anchor" href="#l142-·-一般过去时被动语态" aria-label="Permalink to &quot;L142 · 一般过去时被动语态 {#l142-·-一般过去时被动语态}&quot;">​</a></h2><p>by email 表方式，不是执行者；被动中的 built 是分词，不是 build 原形。</p><p><strong>对照例句：</strong> This bridge was built fifty years ago.</p><p>This bridge 为动作承受者，was built 为单数过去被动；fifty years ago 为明确过去时间。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-142">回看讲解和练习</a></p><h2 id="l143-·-现在完成时与将来时被动" tabindex="-1">L143 · 现在完成时与将来时被动 <a class="header-anchor" href="#l143-·-现在完成时与将来时被动" aria-label="Permalink to &quot;L143 · 现在完成时与将来时被动 {#l143-·-现在完成时与将来时被动}&quot;">​</a></h2><p>has been cleared 不能省略 been；will be planted 中 be 不写成 been。</p><p><strong>对照例句：</strong> The path has been cleared of fallen branches.</p><p>The path 是清理对象，has been cleared 为现在完成时被动；of fallen branches 说明被清除的东西。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-143">回看讲解和练习</a></p><h2 id="l144-·-现在完成时与将来时被动" tabindex="-1">L144 · 现在完成时与将来时被动 <a class="header-anchor" href="#l144-·-现在完成时与将来时被动" aria-label="Permalink to &quot;L144 · 现在完成时与将来时被动 {#l144-·-现在完成时与将来时被动}&quot;">​</a></h2><p>has been cleared 不能省略 been；will be planted 中 be 不写成 been。</p><p><strong>对照例句：</strong> New trees will be planted beside the stream.</p><p>New trees 是被种植对象，will be planted 为将来时被动；beside the stream 表未来种植位置。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-144">回看讲解和练习</a></p>',68)])])}const f=a(i,[["render",o]]);export{g as __pageData,f as default};
